#!/usr/bin/env python3
# SCOPE: this task delivers the GENERATOR. `pool.json` gains inject entries only when `generate` is run against real
#        staged parts under a pinned mesh image; hosting the output is blocked on the ABC/OCCT redistribution
#        question (an owner decision, not made here). No real entries are generated by this change.
# Responsibility: Turn clean pool parts into injected-defect pool entries: apply Task 7's structural injectors,
#                 write the damaged STEP files into an upload tree, and add `inject` entries to the pool manifest
#                 with the provenance that lets every one be regenerated byte-for-byte.
# Owns: the kind and source guards, STEP header normalisation (what makes the bytes reproducible), the
#       `injected.json` recipe sidecar, regeneration (`verify`) and the pool/recipe consistency check.
# Boundaries: it does NOT define injectors (inject.py, Task 7), probe gmsh (Task 8), fetch (stage.py, Task 8c) or
#             upload. The damaged files are written to `--out` as `<sha256>/<basename>`; whoever serves that tree
#             at `--base-url` (a bucket, or any HTTP host) makes the entries fetchable by the stager UNMODIFIED:
#             an entry is a direct file (`archive_sha256` None) at `<base-url>/<sha256>/<basename>`, which the
#             stager downloads and hashes whole. Nothing here uploads anything.
"""Generate the injected-defect part of the CRS v4 benchmark pool.

    inject_pool.py generate --pool P --inputs STAGED --out TREE --base-url URL --image-digest SHA [--kinds ...]
    inject_pool.py verify   --pool P --inputs STAGED [--image-digest SHA]

SCOPE: this module is the generator. It adds inject entries to `pool.json` only when `generate` is run on real
staged parts under a pinned image; hosting them is blocked on the ABC/OCCT redistribution question.

`generate` takes clean parts (sources abc_pass, occt, nist) that the stager has already placed at
`<inputs>/<sha256>/<basename>`, applies each requested kind for seeds 0..N-1, and REPLACES the manifest's inject
set MERGED BY RECIPE: a recipe is (clean source sha256, kind, seed); a run replaces the records for the recipes it
regenerated and keeps every other record, so a partial (`--max-sources`) run can never truncate the benchmark.
`verify` re-runs every recipe from its clean source and fails unless the bytes hash to the manifest again.

The canonical benchmark artifact is the HOSTED FILE, addressed by its sha256. Regeneration is an AUDIT under the
pinned image, never a runtime dependency. Each record therefore names the build that made it (`occt_version`,
`image_digest` of the mesh image, `inject_revision` = sha256 of inject.py); `verify` prints them and warns loudly
when the running build differs, because an OCCT upgrade can change every hash and that is an explanation, not a
mystery. `generate` refuses to run without `--image-digest` (or $V4_MESH_IMAGE_DIGEST) and a resolvable OCCT version.

Joining the label: the defect label is in `injected.json`, NOT `pool.json`. A consumer holding a pool entry joins on
`sha256`: `records[i].sha256 == entry.sha256` gives `label`, `kind`, `seed` and the clean source.

What is refused, and why:
  kinds   only `inject.DEFAULT_KINDS` (the five structural kinds). The four QUARANTINED kinds read back as valid
          solids with only a raised tolerance - clean by our own metric - so including them would pad the failing
          set with files that are not failing. `pcurve_corrupt` is infeasible (the STEP reader rebuilds pcurves).
  sources abc_pass, occt, nist. Not abc_fail (not clean), not inject (no damage on damage), and not f360: the
          Fusion 360 licence is not cleared for redistribution (the stager holds it for the same reason).

Design 7.2: for an injected file "the original" used for fidelity is the DAMAGED INPUT, never the clean source.
The clean source is used ONLY to label the defect: it appears in the recipe as `source_*` and in the label as
`clean_source`, and `label["fidelity_reference"]` says "damaged_input". Nothing here points a fidelity measure at it.

Licence: an injected variant of a part is governed by that part's terms, so each entry's licence is its clean
source's licence text verbatim; `check_pool` fails any entry whose licence differs.

Reproducibility: OCCT's STEP writer takes values from its environment, so two runs of the same
(source, kind, seed) differ by them: the wall clock in the `FILE_NAME` header, and process-wide counters (the
PRODUCT name "Open CASCADE STEP translator 7.9 <N>", and the ids of NEXT_ASSEMBLY_USAGE_OCCURRENCE). Both were
found by diffing real runs. `normalize_step` pins them; with it the file is a function of (source bytes, kind,
seed, OCCT build, inject.py), and `verify` proves that on the build you run it on, in a fresh process.
"""
from __future__ import annotations

import argparse
import hashlib
import importlib.util
import json
import os
import re
import sys
import tempfile
from collections import Counter
from collections.abc import Callable, Sequence
from dataclasses import asdict, dataclass
from pathlib import Path
from typing import Any

HERE = Path(__file__).resolve().parent
RECORDS = HERE.parents[0] / "corpora/v4/injected.json"


def _load(name: str, path: Path) -> Any:
    if name in sys.modules:
        return sys.modules[name]
    spec = importlib.util.spec_from_file_location(name, path)
    assert spec is not None and spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    sys.modules[name] = module  # dataclasses resolve annotations through sys.modules
    spec.loader.exec_module(module)
    return module


pool: Any = _load("v4_pool", HERE / "pool.py")
PoolEntry = pool.PoolEntry


def load_backend() -> Any:
    """inject.py, loaded lazily: it imports OCP, which only the native tier has."""
    return _load("v4_eval_inject", HERE / "inject.py")


#: Pool sources that are clean parts. abc_fail is not clean, inject is already damaged, f360 is licence-held.
CLEAN_SOURCES: frozenset[str] = frozenset({"abc_pass", "occt", "nist"})
#: Bumped if `normalize_step` ever changes what it writes: old recipes then regenerate with their own version.
#: Semantic edits it makes, benign for geometry but visible to a checker keying on them: every PRODUCT name collapses
#: to the same "Open CASCADE STEP translator <ver> 1" (so distinct product names in an assembly, e.g. the
#: `assembly_overlap` kind, become identical), and occurrence ids are renumbered 1, 2, ... in file order.
NORMALIZER = "step-environment-counters/1"
_EPOCH = b"1970-01-01T00:00:00"
# OCCT names the PRODUCT "Open CASCADE STEP translator 7.9 <N>", N being how many STEP files this PROCESS has
# written so far. A fresh process and a long-lived one therefore disagree; the count means nothing.
_TRANSLATOR_COUNT = re.compile(rb"(Open CASCADE STEP translator \d+(?:\.\d+)*) \d+")
# Assembly occurrences are likewise labelled with a process-wide counter ('NEXT_ASSEMBLY_USAGE_OCCURRENCE('7'...);
# renumbered 1, 2, ... in file order, which is a function of the shape.
_OCCURRENCE_ID = re.compile(rb"(NEXT_ASSEMBLY_USAGE_OCCURRENCE\s*\(\s*')\d+(')")
_HEADER_STAMP = re.compile(rb"(FILE_NAME\s*\(\s*'[^']*'\s*,\s*')(\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d)(')")

INJECT_NOTE: str = pool.INJECT_NOTE


_OCCT_DISTRIBUTIONS = ("cadquery-ocp", "cadquery-ocp-novtk", "ocp")


def occt_version(backend: Any) -> str:
    """The OCCT build in use: the backend's own answer, else the installed OCP wheel's version (read from package
    metadata, so no OCP import). "" if neither is known."""
    ask = getattr(backend, "occt_version", None)
    if callable(ask):
        return str(ask())
    from importlib import metadata
    for dist in _OCCT_DISTRIBUTIONS:
        try:
            return f"{dist}=={metadata.version(dist)}"
        except metadata.PackageNotFoundError:
            continue
    return ""


def current_environment(backend: Any, image_digest: str | None) -> Environment:
    revision = hashlib.sha256((HERE / "inject.py").read_bytes()).hexdigest()
    return Environment(occt_version(backend), image_digest or "", revision)


def environment_mismatches(r: Any, env: Environment) -> list[str]:
    """How the build recorded on a recipe differs from the running one (an unrecorded field counts)."""
    out = []
    for field, label in (("occt_version", "OCCT version"), ("image_digest", "mesh image digest"),
                         ("inject_revision", "inject.py revision")):
        recorded, running = getattr(r, field), getattr(env, field)
        if recorded != running:
            out.append(f"{label}: recorded {recorded or '<unrecorded>'}, running {running or '<unknown>'}")
    return out


class GenerationError(RuntimeError):
    """The generator cannot produce a trustworthy entry (bad source hash, un-normalisable output)."""


class RefusedKind(ValueError):
    """A kind outside DEFAULT_KINDS: quarantined, infeasible or unknown."""


class RefusedSource(ValueError):
    """A pool source that is not a clean, cleared part."""


@dataclass(frozen=True)
class Recipe:
    """Everything needed to regenerate one injected file, and the label of its defect."""
    name: str
    sha256: str               # of the damaged, normalised file
    source_name: str          # the clean part in the pool
    source_sha256: str
    source_source: str        # that part's pool source (abc_pass / occt / nist)
    kind: str
    seed: int
    label: dict[str, Any]
    normalizer: str = NORMALIZER
    occt_version: str = ""    # the build that wrote the bytes; "" = unrecorded
    image_digest: str = ""    # digest of the mesh image it ran in
    inject_revision: str = ""  # sha256 of inject.py


@dataclass(frozen=True)
class Environment:
    """The build a set of hashes is a function of."""
    occt_version: str
    image_digest: str
    inject_revision: str


def recipe_key(r: Any) -> tuple[str, str, int]:
    return (r.source_sha256, r.kind, r.seed)


@dataclass(frozen=True)
class Skipped:
    source_name: str
    source_sha256: str
    kind: str
    seed: int
    reason: str


@dataclass
class GenerateResult:
    entries: list[Any]
    recipes: list[Recipe]
    skipped: list[Skipped]


# --------------------------------------------------------------------------- guards

def check_kind(kind: str, backend: Any) -> None:
    """Raise RefusedKind unless `kind` is one of the injector's DEFAULT_KINDS, or its labelled declined stratum
    (ADMITTED_KINDS: opt-in by name, never part of a default draw)."""
    status = backend.KIND_STATUS.get(kind)
    admitted = getattr(backend, "ADMITTED_KINDS", backend.DEFAULT_KINDS)
    if status is None:
        raise RefusedKind(f"unknown injector kind {kind!r}; the structural kinds are "
                          f"{', '.join(backend.DEFAULT_KINDS)}")
    if kind not in admitted:
        why = ("its damage is unproven: it reads back as a valid solid with only a raised tolerance, i.e. clean "
               "by our own metric" if status == "quarantined" else "no damage survives the STEP reader")
        raise RefusedKind(f"{kind} is {status}, not structural: {why}; only {', '.join(backend.DEFAULT_KINDS)} "
                          f"may enter the benchmark")


def resolve_kinds(kinds: Sequence[str] | None, backend: Any) -> list[str]:
    chosen = list(kinds) if kinds else list(backend.DEFAULT_KINDS)
    for kind in chosen:
        check_kind(kind, backend)
    return chosen


def check_source(entry: Any) -> None:
    if entry.source not in CLEAN_SOURCES:
        held = " (the Fusion 360 licence is not cleared for redistribution)" if entry.source == "f360" else ""
        raise RefusedSource(f"{entry.name}: source {entry.source!r} is not a clean part to inject into{held}; "
                            f"allowed: {', '.join(sorted(CLEAN_SOURCES))}")


# --------------------------------------------------------------------------- normalisation and one injection

def normalize_step(data: bytes) -> bytes:
    """Pin what OCCT's STEP writer takes from its environment, not from the shape: the wall-clock stamp in the
    FILE_NAME header, and the process-wide counters in the PRODUCT name and in assembly-occurrence ids.
    Nothing else changes."""
    head, sep, tail = data.partition(b"DATA;")
    fixed, n = _HEADER_STAMP.subn(rb"\g<1>" + _EPOCH + rb"\g<3>", head, count=1)
    if n != 1:
        raise GenerationError("no FILE_NAME timestamp in the STEP header; cannot make the bytes reproducible")
    body = _TRANSLATOR_COUNT.sub(rb"\g<1> 1", fixed + sep + tail)
    ordinal = iter(range(1, len(body)))
    return _OCCURRENCE_ID.sub(lambda m: m.group(1) + str(next(ordinal)).encode() + m.group(2), body)


def _portable_label(raw: dict[str, Any], source: Any, work: Path) -> dict[str, Any]:
    label = {k: v for k, v in raw.items() if k != "iges_file"}      # a temp path: meaningless off this machine
    label["clean_source"] = source.name                              # labels the defect; NEVER a fidelity reference
    label["clean_source_sha256"] = source.sha256
    label["fidelity_reference"] = "damaged_input"
    text = json.dumps(label, sort_keys=True)                         # also proves it serialises
    if str(work) in text:
        raise GenerationError(f"label for {source.name} still names a temp path")
    return json.loads(text)


def damage(source: Any, path: Path, kind: str, seed: int, backend: Any) -> tuple[bytes, dict[str, Any]]:
    """The one place a damaged file is made, for `generate` and `verify` alike: inject, normalise, sanitise."""
    got = pool.sha256_file(path)
    if got != source.sha256:
        raise GenerationError(f"{source.name}: file {path} has sha256 {got}, the pool says {source.sha256}")
    with tempfile.TemporaryDirectory(prefix="v4-inject-pool-") as tmp:
        work = Path(tmp)
        case = backend.inject(path, kind, seed, work)
        data = normalize_step(case.path.read_bytes())
        return data, _portable_label(case.label, source, work)


def _basename(source_name: str, sha: str, kind: str, seed: int) -> str:
    return f"{sha[:12]}_{Path(source_name).stem}.{kind}.{seed}.step"


def generate(clean: Sequence[tuple[Any, Path]], *, kinds: Sequence[str] | None, seeds: Sequence[int],
             out_dir: Path, base_url: str, backend: Any, environment: Environment | None = None) -> GenerateResult:
    """Inject every (clean part, kind, seed); write each file to `<out_dir>/<sha256>/<basename>`.

    Guards run before the first injection and before anything is written. Only InjectionNotApplicable is
    reported in `skipped`; InjectionInfeasible and every other exception (a STEP read error, a bug) propagate.
    Each recipe records `environment` (OCCT version, image digest, inject.py revision)."""
    chosen = resolve_kinds(kinds, backend)
    for source, _path in clean:
        check_source(source)
    base = base_url.rstrip("/")
    if not base:
        raise GenerationError("base_url is required: it is what makes the entries fetchable")
    env = environment if environment is not None else Environment("", "", "")
    result = GenerateResult([], [], [])
    seen: dict[str, str] = {}
    for source, path in clean:
        for kind in chosen:
            for seed in seeds:
                try:
                    data, label = damage(source, path, kind, seed, backend)
                except backend.InjectionNotApplicable as exc:
                    result.skipped.append(Skipped(source.name, source.sha256, kind, seed,
                                                  re.sub(r"\S*v4-inject-pool-\w+/", "", str(exc))))
                    continue
                sha = hashlib.sha256(data).hexdigest()
                if sha in seen:
                    result.skipped.append(Skipped(source.name, source.sha256, kind, seed,
                                                  f"byte-identical to {seen[sha]}"))
                    continue
                base_name = _basename(source.name, source.sha256, kind, seed)
                target = out_dir / sha / base_name
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_bytes(data)
                name = f"inject/{base_name}"
                seen[sha] = name
                result.recipes.append(Recipe(name, sha, source.name, source.sha256, source.source, kind, seed, label,
                                             NORMALIZER, env.occt_version, env.image_digest, env.inject_revision))
                # Task 8f's `pool.inject_entry` is THE adapter: it derives the licence from the clean
                # source (never accepts one) and carries the injector label's kind/status, which the
                # merged quarantine gate requires. Building a PoolEntry here directly would set no
                # kind_status, and every inject entry would then be refused.
                result.entries.append(pool.inject_entry(source, name=name, sha256=sha,
                                                        url=f"{base}/{sha}/{base_name}", label=label))
    return result


# --------------------------------------------------------------------------- regeneration and consistency

def verify(recipes: Sequence[Recipe], entries: Sequence[Any], source_path: Callable[[str], Path | None],
           backend: Any, environment: Environment | None = None) -> list[str]:
    """Regenerate every recipe from its clean source. Returns problems; empty means every entry is reproducible.

    When `environment` is given and a recipe was made by a different build, a hash difference is reported WITH that
    explanation (an OCCT upgrade is the expected cause), not as a bare "differs".

    A source that cannot be found is a problem, never a skip: an entry nobody can regenerate is not a benchmark."""
    by_sha = {e.sha256: e for e in entries}
    problems: list[str] = []
    for r in recipes:
        try:
            check_kind(r.kind, backend)
        except RefusedKind as exc:
            problems.append(f"{r.name}: {exc}")
            continue
        path = source_path(r.source_sha256)
        if path is None or not path.is_file():
            problems.append(f"{r.name}: clean source {r.source_name} ({r.source_sha256}) is not available; "
                            f"cannot regenerate")
            continue
        if r.sha256 not in by_sha:
            problems.append(f"{r.name}: {r.sha256} is not in the pool entries")
        source = PoolEntry(r.source_name, r.source_source, r.source_sha256, "", None, "x")
        try:
            data, label = damage(source, path, r.kind, r.seed, backend)
        except Exception as exc:  # noqa: BLE001 - any failure to regenerate is the finding
            problems.append(f"{r.name}: regeneration failed: {type(exc).__name__}: {exc}")
            continue
        got = hashlib.sha256(data).hexdigest()
        if got != r.sha256:
            why = environment_mismatches(r, environment) if environment is not None else []
            because = (f"; EXPECTED, the build differs ({'; '.join(why)}): re-run under the recorded image"
                       if why else "")
            problems.append(f"{r.name}: regenerated sha256 {got} differs from the manifest {r.sha256} "
                            f"({r.kind}, seed {r.seed}){because}")
        elif label != r.label:
            problems.append(f"{r.name}: regenerated bytes match but the label differs from the recorded one")
    return problems


def check_pool(pool_entries: Sequence[Any], recipes: Sequence[Recipe], backend: Any) -> list[str]:
    """Offline consistency between the manifest's inject entries and the recipes. Returns problems."""
    problems: list[str] = []
    inject_entries = {e.sha256: e for e in pool_entries if e.source == "inject"}
    clean = {e.sha256: e for e in pool_entries if e.source != "inject"}
    by_sha = {r.sha256: r for r in recipes}
    for sha, e in inject_entries.items():
        if sha not in by_sha:
            problems.append(f"{e.name}: inject entry has no recipe, so it cannot be regenerated")
    for r in recipes:
        entry = inject_entries.get(r.sha256)
        if entry is None:
            problems.append(f"{r.name}: recipe has no pool entry")
        else:
            if entry.name != r.name:
                problems.append(f"{r.name}: pool entry is named {entry.name!r}")
            if entry.archive_sha256 is not None or not entry.url.endswith(f"/{r.sha256}/{Path(r.name).name}"):
                problems.append(f"{r.name}: url {entry.url!r} is not a direct file at <base>/{r.sha256}/"
                                f"{Path(r.name).name}, which the stager cannot verify")
        try:
            check_kind(r.kind, backend)
        except RefusedKind as exc:
            problems.append(f"{r.name}: {exc}")
        source = clean.get(r.source_sha256)
        if source is None:
            problems.append(f"{r.name}: clean source {r.source_name} ({r.source_sha256}) is not in the pool")
            continue
        if source.source not in CLEAN_SOURCES:
            problems.append(f"{r.name}: clean source is from {source.source!r}, not a cleared clean source")
        if entry is not None and entry.licence != source.licence:
            problems.append(f"{r.name}: licence differs from its clean source's; an injected variant is "
                            f"governed by its source's terms")
    return problems


# --------------------------------------------------------------------------- the sidecar and the manifest

def merge_generated(existing: Sequence[Recipe], existing_skipped: Sequence[dict[str, Any]],
                    existing_entries: Sequence[Any], result: GenerateResult
                    ) -> tuple[list[Recipe], list[dict[str, Any]], list[Any]]:
    """Merge a run into what is already recorded, by recipe (source sha256, kind, seed). The run's recipes replace
    same-keyed ones; every other existing record, skip and inject entry is kept, so a partial run adds or refreshes
    and never deletes. A kept record whose file hash collides with a new one yields to the new one."""
    new_keys = {recipe_key(r) for r in result.recipes}
    new_shas = {r.sha256 for r in result.recipes}
    kept = [r for r in existing if recipe_key(r) not in new_keys and r.sha256 not in new_shas]
    kept_shas = {r.sha256 for r in kept}
    skipped_keys = new_keys | {(x.source_sha256, x.kind, x.seed) for x in result.skipped}
    skipped = [x for x in existing_skipped if (x["source_sha256"], x["kind"], x["seed"]) not in skipped_keys]
    skipped += [asdict(x) for x in result.skipped]
    entries = [e for e in existing_entries if e.sha256 in kept_shas] + list(result.entries)
    return kept + result.recipes, skipped, entries


def read_skipped(path: Path) -> list[dict[str, Any]]:
    return list(json.loads(path.read_text()).get("skipped") or []) if path.exists() else []


def write_records(path: Path, recipes: Sequence[Recipe], *, skipped: Sequence[Skipped | dict[str, Any]]) -> None:
    doc = {"version": 1, "normalizer": NORMALIZER, "note": INJECT_NOTE,
           "records": [asdict(r) for r in sorted(recipes, key=lambda r: r.sha256)],
           "skipped": [s if isinstance(s, dict) else asdict(s) for s in skipped]}
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(doc, separators=(",", ":"), sort_keys=True) + "\n")


def read_records(path: Path, backend: Any | None = None) -> list[Recipe]:
    doc = json.loads(path.read_text())
    if doc.get("version") != 1:
        raise ValueError(f"{path}: records version {doc.get('version')}, expected 1")
    backend = backend if backend is not None else load_backend()
    recipes = [Recipe(**row) for row in doc["records"]]
    for r in recipes:
        check_kind(r.kind, backend)
    return recipes


def merge_into_pool(manifest: Path, entries: Sequence[Any]) -> None:
    """Replace the manifest's inject entries with `entries`; every other entry, and the manifest's notes, stay.
    The manifest's `deduped` is what THIS merge dropped, not a running total across regenerations."""
    doc = json.loads(manifest.read_text())
    kept = [e for e in pool.read_pool(manifest) if e.source != "inject"]
    merged, dropped = pool.merge_pool([pool.StaticSource(kept), pool.StaticSource(entries)])
    included = list(doc.get("sources_included") or [])
    if "inject" not in included:
        included.append("inject")
    notes = {**(doc.get("source_notes") or {}), "inject": INJECT_NOTE}
    pool.write_pool(merged, manifest, sources_included=included,
                    deduped=len(dropped), notes=notes)


# --------------------------------------------------------------------------- CLI

def _staged(inputs: Path, entry: Any) -> Path:
    return inputs / entry.sha256 / Path(entry.name).name


def main(argv: list[str] | None = None, *, backend: Any | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = parser.add_subparsers(dest="cmd", required=True)
    g = sub.add_parser("generate")
    g.add_argument("--pool", default=str(pool.OUT))
    g.add_argument("--inputs", required=True, help="the stager's output dir: clean parts at <sha256>/<basename>")
    g.add_argument("--out", required=True, help="tree to write damaged files to, as <sha256>/<basename>")
    g.add_argument("--base-url", required=True, help="where --out will be served; becomes each entry's url")
    g.add_argument("--records", default=str(RECORDS))
    g.add_argument("--image-digest", default=None,
                   help="digest of the mesh image this runs in (or $V4_MESH_IMAGE_DIGEST); recorded on every recipe")
    g.add_argument("--kinds", default=None, help="comma-separated; default is the five structural kinds")
    g.add_argument("--seeds", type=int, default=1, help="seeds per (part, kind): seed-base .. seed-base+N-1")
    g.add_argument("--seed-base", type=int, default=0)
    g.add_argument("--max-sources", type=int, default=None, help="clean parts to use (hash order); default all")
    g.add_argument("--sources", default="abc_pass,occt,nist", help="comma-separated clean pool sources")
    v = sub.add_parser("verify")
    v.add_argument("--pool", default=str(pool.OUT))
    v.add_argument("--inputs", required=True)
    v.add_argument("--records", default=str(RECORDS))
    v.add_argument("--image-digest", default=None, help="digest of the image verify runs in, to compare with the "
                                                        "recorded one (or $V4_MESH_IMAGE_DIGEST)")
    args = parser.parse_args(argv)
    try:
        backend = backend if backend is not None else load_backend()
        manifest = Path(args.pool)
        entries = pool.read_pool(manifest)
        if args.cmd == "generate":
            return _cmd_generate(args, entries, manifest, backend)
        return _cmd_verify(args, entries, backend)
    except (RefusedKind, RefusedSource, GenerationError) as exc:
        print(f"REFUSED: {exc}", file=sys.stderr)
        return 2


def _cmd_generate(args: argparse.Namespace, entries: list[Any], manifest: Path, backend: Any) -> int:
    wanted = [s for s in args.sources.split(",") if s]
    for s in wanted:
        if s not in CLEAN_SOURCES:
            raise RefusedSource(f"--sources {s!r} is not a clean source; allowed: {', '.join(sorted(CLEAN_SOURCES))}")
    kinds = resolve_kinds(args.kinds.split(",") if args.kinds else None, backend)
    inputs = Path(args.inputs)
    candidates = sorted((e for e in entries if e.source in wanted), key=lambda e: (e.sha256, e.name))
    present = [e for e in candidates if _staged(inputs, e).is_file()]
    print(f"{len(candidates)} clean candidate(s) in the pool, {len(present)} staged under {inputs}", flush=True)
    chosen = present[: args.max_sources] if args.max_sources is not None else present
    if not chosen:
        raise GenerationError("no clean part is staged; run stage.py first (nothing was written)")
    env = current_environment(backend, args.image_digest or os.environ.get("V4_MESH_IMAGE_DIGEST"))
    if not env.image_digest or not env.occt_version:
        raise GenerationError("cannot pin the build: need --image-digest (or $V4_MESH_IMAGE_DIGEST) and a "
                              f"resolvable OCCT version (got digest {env.image_digest!r}, OCCT "
                              f"{env.occt_version!r}); an unpinned entry cannot be audited later")
    print(f"pinned to {env}", flush=True)
    result = generate([(e, _staged(inputs, e)) for e in chosen], kinds=kinds,
                      seeds=range(args.seed_base, args.seed_base + args.seeds), out_dir=Path(args.out),
                      base_url=args.base_url, backend=backend, environment=env)
    if not result.entries:
        raise GenerationError(f"nothing was injected ({len(result.skipped)} skipped); manifest left alone")
    records_path = Path(args.records)
    existing = read_records(records_path, backend) if records_path.exists() else []
    recipes, skipped, merged_entries = merge_generated(
        existing, read_skipped(records_path), [e for e in entries if e.source == "inject"], result)
    write_records(records_path, recipes, skipped=skipped)
    merge_into_pool(manifest, merged_entries)
    per_kind = Counter(r.kind for r in result.recipes)
    print(f"merged by recipe: {len(result.entries)} new/refreshed, {len(recipes)} recorded in total")
    print(f"wrote {len(result.entries)} inject entries from {len(chosen)} clean part(s) "
          f"{dict(sorted(per_kind.items()))}; {len(result.skipped)} skipped (not applicable); files under "
          f"{args.out}, recipes {args.records}, manifest {manifest}. NOTHING UPLOADED: serve {args.out} at "
          f"{args.base_url}")
    for s in result.skipped:
        print(f"  skipped {s.kind} seed {s.seed} on {s.source_name}: {s.reason}", file=sys.stderr)
    return 0


def _cmd_verify(args: argparse.Namespace, entries: list[Any], backend: Any) -> int:
    recipes = read_records(Path(args.records), backend)
    by_sha = {e.sha256: e for e in entries if e.source != "inject"}
    inputs = Path(args.inputs)

    def source_path(sha: str) -> Path | None:
        entry = by_sha.get(sha)
        return _staged(inputs, entry) if entry is not None else None

    env = current_environment(backend, args.image_digest or os.environ.get("V4_MESH_IMAGE_DIGEST"))
    seen: set[tuple[str, ...]] = set()
    for r in recipes:
        diff = environment_mismatches(r, env)
        if diff and tuple(diff) not in seen:
            seen.add(tuple(diff))
            print("WARNING BUILD MISMATCH: these records were made by a different build than this one; "
                  "hashes may legitimately differ. The hosted file (by sha256) is the canonical artifact; "
                  f"regenerating is an audit under the recorded image. {'; '.join(diff)}", file=sys.stderr)
    problems = check_pool(entries, recipes, backend) + verify(
        recipes, [e for e in entries if e.source == "inject"], source_path, backend, env)
    for p in problems:
        print(f"PROBLEM {p}", file=sys.stderr)
    print(f"{len(recipes)} recipe(s) checked, {len(problems)} problem(s)")
    return 1 if problems else 0


if __name__ == "__main__":
    raise SystemExit(main())
